for role,total,offset in [('fit',640000,0),('select',256,50000),('cal',256,60000)]:
   rng=np.random.default_rng(sample_seed+offset);rr=[];bb=[];cc=[];drawn=0;rejected=0
   pools={s:[j for j,r in enumerate(rows) if r['role']==role and r['dataset']==s] for s in sources}
   assert all(pools.values())
   for n in range(total):
    domain=sources[(n//64)%len(sources)]
    for _ in range(1000):
     j=int(rng.choice(pools[domain]));r=rows[j];b=int(r['forecast_origins'][rng.integers(len(r['forecast_origins']))]);c=int(rng.integers(len(r['columns'])))
     ar=sampler.array(r);x=ar[b-400:b,c];y=ar[b:b+5,c];drawn+=1
     ok=np.isfinite(x[0]) and not np.isinf(x).any() and not np.isinf(y).any() and np.isfinite(y).any()
     if ok:break
     rejected+=1
    else:raise ValueError('No eligible source tuple; never relax quality or role rules')
    rr.append(j);bb.append(b);cc.append(c)
   arrays[role+'_record']=np.array(rr,dtype='uint16');arrays[role+'_origin']=np.array(bb,dtype='uint32');arrays[role+'_channel']=np.array(cc,dtype='uint8')
   quality[role]={'requested':total,'drawn':drawn,'rejected':rejected,'rng_seed':sample_seed+offset}
   print('PLAN',planname,role,total,flush=True)
